use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path,collections::BTreeMap,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/component-partition175";const Z:&str="/home/ubuntu/src/zk-tools/zopro";
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let root=Path::new(R);let z=Path::new(Z);let m:Value=serde_json::from_slice(&fs::read(z.join("docs/benchmarks/2026-10-29-balanced-kh-adoption/artifacts/production-source-manifest.json")).unwrap()).unwrap();let setup=fs::read_to_string(root.join("setup.rs")).unwrap();let raw=|name:&str|setup.split_once(&format!("let {name}=r#\"")).unwrap().1.split_once("\"#;").unwrap().0;
    let phi="crates/zopro-core/src/msm_affine/g2_phi.rs";let borrowed="crates/zopro-core/src/msm_affine/g2_borrowed.rs";let workspace="crates/zopro-core/src/msm_affine/workspace.rs";let mut exact=0;let mut pins=BTreeMap::new();
    for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(z.join(p)),h.as_str().unwrap());let original=fs::read(z.join(p)).unwrap();let actual=fs::read(root.join("source").join(p)).unwrap();let expected=if p==phi{let before="    hb_raw(bases, words, 12, 2)";let after=format!("    #[cfg(zopro_phi_component_partition)]\n    if let Some(value)=partition::try_raw(bases,words) {{return value;}}\n{before}");format!("{}\n#[cfg(any(test,zopro_phi_component_partition))]\nmod partition;\n",String::from_utf8(original.clone()).unwrap().replacen(before,&after,1)).into_bytes()}else if p==borrowed{format!("{}{}",String::from_utf8(original.clone()).unwrap(),raw("suffix")).into_bytes()}else if p==workspace{format!("{}{}",String::from_utf8(original.clone()).unwrap().replacen("        q.leaf=q.leaf.max(top.leaf);p=p.maximum(q);",raw("revised"),1),raw("test")).into_bytes()}else{original.clone()};assert_eq!(actual,expected,"final source {p}");if actual==original{exact+=1;}pins.insert(p.clone(),hash(root.join("source").join(p)));}
    assert_eq!(exact,172);assert_eq!(hash(root.join("partition.rs")),hash(root.join("source/crates/zopro-core/src/msm_affine/g2_phi/partition.rs")));
    let mut code=BTreeMap::new();for label in["control","candidate"]{let binary=root.join(format!("native/{label}-sdk"));let out=Command::new("nm").args(["-S","--defined-only"]).arg(&binary).output().unwrap();assert!(out.status.success());let text=String::from_utf8(out.stdout).unwrap();let selected=text.lines().filter(|l|l.contains("g2_phi")&&l.contains("partition")).collect::<Vec<_>>();code.insert(label,json!({"binary":binary,"sha256":hash(&binary),"partition_symbol_contexts":selected}));}
    fs::write(root.join("final-source-review.json"),serde_json::to_vec_pretty(&json!({"all175_production_hashes_verified":true,"all175_private_files_match_exact_declared_edits":true,"originals_exact":exact,"field17_exact":true,"reverse175_exact":true,"private_hashes":pins,"code":code,"prebuild_preparation_corrections_preserved":true})).unwrap()).unwrap();println!("Final source review passes:175 exact declared edits/172 unchanged; no source adoption");
}
